import{_ as d,C as e,o,c as s,E as a,a2 as l}from"./chunks/framework.uPk2SrVb.js";const g=JSON.parse('{"title":"同为半分，覆盖为何不同：科学工作流评分的解释边界","description":"","frontmatter":{"title":"同为半分，覆盖为何不同：科学工作流评分的解释边界","date":"2026-10-27","column":"industry-architecture","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"科学工作流总分会掩盖哪些覆盖、条件质量与聚合差异？","summary":"四个查询上的两组构造输出都得到 0.5 分，却分别覆盖全部和一半查询。有限公式实验说明，解读科学工作流评测需要保留覆盖、条件通过率、任务权重与指标有效性的分账。","sources":["https://arxiv.org/html/2610.07763v1"],"pageClass":"runtime-v6-article","item_id":"SIG-20261027-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-27-sig-20261027-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-10-27-sig-20261027-005.md","filePath":"zh/industry/2026-10-27-sig-20261027-005.md","lastUpdated":null}'),n={name:"zh/industry/2026-10-27-sig-20261027-005.md"};function h(p,t,c,u,m,_){const r=e("ArticleCover"),i=e("ArticleTableScroll");return o(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-10-27-sig-20261027-005-cover.png",kicker:"研究成果",title:"同为半分，覆盖为何不同：科学工作流评分的解释边界",summary:"四个查询上的两组构造输出都得到 0.5 分，却分别覆盖全部和一半查询。有限公式实验说明，解读科学工作流评测需要保留覆盖、条件通过率、任务权重与指标有效性的分账。",version:"2026-10-27",languageHref:"/en/industry/2026-10-27-sig-20261027-005",languageLabel:"English"}),a(i,{language:"zh"}),t[0]||(t[0]=l('<h1 id="同为半分-覆盖为何不同-科学工作流评分的解释边界" tabindex="-1">同为半分，覆盖为何不同：科学工作流评分的解释边界 <a class="header-anchor" href="#同为半分-覆盖为何不同-科学工作流评分的解释边界" aria-label="Permalink to &quot;同为半分，覆盖为何不同：科学工作流评分的解释边界&quot;">​</a></h1><p>四个查询，一组系统全部给出满足数值过滤条件的输出，其中两个达到任务目标；另一组只给出两个满足过滤条件的输出，但两个都达标。按本文采用的评分公式，两者均为 0.5 分。选型者若只保留总分，就无法知道改进来自覆盖更多问题，还是已覆盖问题上的达标比例更高。</p><p>这个对照来自同日完成的内部构造实验，不是两套真实系统的测量。它针对 ST-Bench（科学研究任务的时空工作流基准）论文第一版附录 C.2（评测指标）、C.3（训练奖励）的定义与描述。本文的判断是：科学工作流的复合分数需要与覆盖率、条件目标通过率、任务权重及指标有效性一起阅读；单个分数无法唯一标识系统行为。[1]</p><h2 id="先看清-有输出-的分母" tabindex="-1">先看清“有输出”的分母 <a class="header-anchor" href="#先看清-有输出-的分母" aria-label="Permalink to &quot;先看清“有输出”的分母&quot;">​</a></h2><p>论文将一种输出称为“符合现实条件的输出”，但其披露的判定首先是操作性的数值过滤：预定义指标可解析、数值有限，至少有一个正值，且没有 −1 哨兵值。这个名字不能直接读成“科学结论已经有效”。[1，附录 C.2]</p><p>作者报告的任务分数，是满足该过滤的查询比例，乘以这些查询中目标达标率的平均值；没有满足条件的输出时记零。若以覆盖率和条件通过率分别表示这两部分，则任务分数为两者之积。论文将 100 个任务分数相加形成汇总分数，因此任务宏平均还需把这个和除以任务数。[1]</p><p>覆盖率回答“多少查询进入了可评分输出集合”，条件通过率回答“进入集合后多少达到指定目标”。后一项不是全部查询上的成功率，也不自动代表领域正确性。两套系统进入集合的查询可能不同，即使条件通过率接近，也不能据此断定它们的科学质量相同。</p><h2 id="两个半分-以及两种平均" tabindex="-1">两个半分，以及两种平均 <a class="header-anchor" href="#两个半分-以及两种平均" aria-label="Permalink to &quot;两个半分，以及两种平均&quot;">​</a></h2><p>内部实验在 Node（脚本执行环境）v24.19.0 中使用构造指标和任务契约，计算论文公式的边界情形。它不调用原基准任务包、不训练智能体，也不重算论文榜单。以下数值是实验的直接结果，属于内部实验依据，不是第三方独立证据。[2]</p><table tabindex="0"><thead><tr><th>构造情形</th><th>查询数</th><th>满足过滤的查询数</th><th>其中达标数</th><th>覆盖率</th><th>条件通过率</th><th>任务分数</th></tr></thead><tbody><tr><td>全部可评分、部分达标</td><td>4</td><td>4</td><td>2</td><td>100%</td><td>50%</td><td>0.5</td></tr><tr><td>部分可评分、全部达标</td><td>4</td><td>2</td><td>2</td><td>50%</td><td>100%</td><td>0.5</td></tr></tbody></table><p>表中每个数值均来自内部构造输入；来源：[2] 的等总分对照。两者在全部查询上的达标数相同，但交付的可评分输出数量不同。总分相同并不意味着工程行为可互换：下游需要完整结果时，未覆盖查询与已输出但未达标的查询，需要不同处置。</p><p>第二组对照让任务规模发生变化：任务一只有 1 个查询且达标，任务二有 9 个查询且全部未达标；两项任务均有完整数值输出。任务分数分别为 1 和 0，宏平均为 0.5，论文式任务分数之和为 1；把 10 个查询合并计算，达标比例则是 0.1。[2]</p><p>这不是某个平均数算错了。按任务等权与按查询等权回答不同问题。我们据此建议，任何汇总值都应同时说明任务数、每项查询数与权重；比较多个评测结果时，应先确认被平均的单位。上述 0.5 与 0.1 来自合成任务，不能代入原论文推算它的真实权重效应。</p><h2 id="数字可接受-仍需领域约束" tabindex="-1">数字可接受，仍需领域约束 <a class="header-anchor" href="#数字可接受-仍需领域约束" aria-label="Permalink to &quot;数字可接受，仍需领域约束&quot;">​</a></h2><p>内部实验还构造了一个单指标零误差输出。即使它满足预设的误差上限目标，因为没有任何正值，仍被所述过滤条件排除。相反，当契约允许另一个正辅助指标时，负误差 −0.5 与辅助值 1 可以一起满足数值过滤，并通过“误差小于上限”的目标检查。作为对照，只有正误差 0.2 的正常输出通过，误差 2 未达标，−1 哨兵值、非有限数与数字字符串分别被拒或不计分。[2]</p><p>负的均方根误差没有领域意义。这个构造说明的是：有限、可解析、至少一个正值等通用规则，与某个指标的物理或数学取值域并非同一层约束。若实际任务另有非负性检查，这个负误差例子就会被挡住。我们没有已验证的任务实现来判断该检查是否存在，正辅助指标也只是实验契约中的假设；不能据此声称基准接受过这样的真实输出。</p><p>同理，从结果文本中提取到一个数值，不足以建立它与某次实际分析执行的对应关系。本文把指标合法性和执行来源列为解读评测时需要的证据，而非宣称原系统必然缺失这些机制。覆盖提升本身可以有价值，这些对照也不否定作者报告的性能增益。</p><h2 id="缺失参考时-奖励有两种读法" tabindex="-1">缺失参考时，奖励有两种读法 <a class="header-anchor" href="#缺失参考时-奖励有两种读法" aria-label="Permalink to &quot;缺失参考时，奖励有两种读法&quot;">​</a></h2><p>测试评分之外，论文还描述训练奖励：数值检查、任务目标、参考接近度的权重分别为 0.10、0.40、0.50。作者称约 7% 查询缺少单智能体参考，并给出剩余两项 0.40、0.60 的权重，同时使用了重新归一化的表述。[1，附录 C.3]</p><p>如果只是按比例归一化剩余的 0.10 与 0.40，结果应为 0.20、0.80。内部实验分别按正文给出的 0.40/0.60 与比例解释的 0.20/0.80 计算。在数值检查为 1、目标通过为 0 的构造输入上，两种奖励为 0.4 与 0.2，相差 0.2；两项都通过时，两种奖励均为 1。[2]</p><p>这里需要保留一个未决点：不知道实际实现采用哪组权重，也不知道作者是否有意改权重。这个差别属于训练奖励解释，不能混入前述测试任务分数，更不能写成已观测到的榜单错误。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文把作者对评测定义和奖励的描述作为来源陈述；本研究中心的公式与构造输入结果属于内部实验依据；关于怎样报告指标的建议属于研究解释。没有独立参与者复现同一基准结果，本轮也未运行上游基准代码。公开预印本提供来源与版本身份，不自动建立科学有效性；引用不意味着背书，同行评审不等于证明，内部实现成功也不能外推为普遍有效。</p><p>[1] 论文作者，论文《ST-Bench（科学研究任务时空基准）：用于科学研究任务多智能体系统生成的时空基准》，公开预印本第一版，2026-10-06，重点为第 3.2、3.3 节及附录 C.2、C.3。<a href="https://arxiv.org/html/2610.07763v1" target="_blank" rel="noreferrer">版本固定的一手论文</a>。本文沿用同日已完成阅读和分析所核验的该版本，未追加研究材料。</p><p>[2] 研究中心内部公式敏感性与构造反例实验，2026-10-27，执行环境为上述脚本环境；输入和输出保留在本文的实验材料中：<a href="/joinwell52/assets/evidence/2026-10-27-sig-20261027-005/experiment-stbench.json">实验结果</a>、<a href="/joinwell52/assets/evidence/2026-10-27-sig-20261027-005/experiment-method.mjs">公式方法脚本</a>。方法脚本从同日已执行分析中抽出本题的计算部分，并与已保存结果核对；这份材料用于复核合成对照，不构成原系统的复现包。</p><h2 id="仍缺哪些可核对材料" tabindex="-1">仍缺哪些可核对材料 <a class="header-anchor" href="#仍缺哪些可核对材料" aria-label="Permalink to &quot;仍缺哪些可核对材料&quot;">​</a></h2><p>对科学智能体评测的使用者，本文支持一项具体检查：要求汇总分数同时附上任务与查询分母、覆盖率、条件达标率、指标合法范围，以及数值对应的执行来源，并单列训练奖励规则。这样才有机会把“更多查询给出可评分结果”与“已覆盖查询更常达标”区分开。</p><p>要进一步评价这套基准的实际行为，还需要已实现的缺失参考权重、逐任务与逐查询记录、指标边界及执行到结果的追溯材料。原始输出和等总计算预算的对照也尚未提供给本次实验。有限公式对照能指出应询问什么，不能替这些缺失材料作答，更不能从中推出多智能体协作的普遍收益。</p>',28))])}const f=d(n,[["render",h]]);export{g as __pageData,f as default};
